from lib import *
S = SS('k83')
F1 = [['enforce=baseline', ''], ['普通 Pod', '通过'], ['privileged / hostNetwork / hostPath / NET_ADMIN', '拒绝'], ['NET_BIND_SERVICE', '通过']]
F2 = [['enforce=restricted', ''], ['普通 Pod', '4 条一起拒绝'], ['补齐 4 项', '通过'], ['只看字段', '不看镜像']]
F3 = [['warn=restricted + enforce=baseline', '创建成功+Warning'], ['enforce=restricted 的 Deployment', '创建成功+Warning'], ['ReplicaSet', 'FailedCreate'], ['readyReplicas', '0']]
F4 = [['已有 privileged Pod', ''], ['dry-run 加标签', 'Warning 列出违规 Pod'], ['真正加标签', '旧 Pod 继续运行'], ['新建 privileged', '被拒']]
PANELS = [('f', 'flow', 'Pod Security 准入'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("命名空间 ps-base 带标签 pod-security.kubernetes.io/enforce=baseline:什么都不设的普通 Pod 通过;privileged: true 被拒(violates PodSecurity \"baseline:latest\": privileged (container \"c\" must not set securityContext.privileged=true));hostNetwork: true 被拒(host namespaces (hostNetwork=true));hostPath 卷被拒(hostPath volumes (volume \"h\"));add NET_ADMIN 被拒(non-default capabilities);add NET_BIND_SERVICE 却通过——baseline 允许少数默认之外的能力。", f=fl(F1, cur=[2], done=[1, 3]), t=tl(S(1), mark=lidx(S(1), 'privileged: true', 'hostNetwork', 'hostPath', 'NET_ADMIN'), done=lidx(S(1), '普通 Pod', 'NET_BIND_SERVICE')), kv=KV([['baseline', '挡住已知的提权手段'], ['拒绝信息', '带字段路径,直接可改'], ['几个例外能力', 'NET_BIND_SERVICE 等在允许名单里']], ['baseline'])),
    step("enforce=restricted:同一个普通 Pod 一次被拒绝 4 条:allowPrivilegeEscalation != false、unrestricted capabilities(要 drop ALL)、runAsNonRoot != true、seccompProfile(要 RuntimeDefault 或 Localhost)。补齐这 4 项(并设 runAsUser: 1000)后创建成功。去掉 runAsUser 但保留 runAsNonRoot: true(镜像其实是 root)也通过——准入只看字段,不看镜像,真正的拒绝要等 kubelet(见上一篇)。", f=fl(F2, cur=[1], done=[2, 3], mark=[0]), t=tl(S(2), mark=lidx(S(2), '普通 Pod:退出码 1'), done=lidx(S(2), '补齐', '去掉 runAsUser')), kv=KV([['restricted', '当前的安全最佳实践'], ['一次列出全部违规', '不用一条条试'], ['只检查字段', '镜像的用户由 kubelet 在运行时拒绝']], ['restricted'])),
    step("warn=restricted + enforce=baseline 的命名空间创建普通 Pod:退出码 0、pod/w1 created,同时返回 Warning: would violate PodSecurity \"restricted:latest\": …。在 enforce=restricted 的命名空间创建不合规的 Deployment:Deployment 本身创建成功(只带 Warning),但 readyReplicas=0,ReplicaSet 的 ReplicaFailure=FailedCreate,事件是 pods \"dep-…\" is forbidden: violates PodSecurity \"restricted:latest\": …——准入拒绝发生在 ReplicaSet 创建 Pod 的那一刻,要到 ReplicaSet 的事件里去看。", f=fl(F3, cur=[1, 2], done=[0, 3]), t=tl(S(3), mark=lidx(S(3), 'warn=restricted + enforce=baseline', 'enforce=restricted 的命名空间里创建不合规的 Deployment'), done=lidx(S(3), 'Deployment 本身创建成功', '事件')), kv=KV([['warn', '只在客户端返回 Warning,不拒绝'], ['Deployment 不被拦', '检查在创建 Pod 时,不是创建控制器时'], ['排查', 'kubectl describe rs / get events']], ['Deployment 不被拦'])),
    step("先在 ps-late 命名空间里创建 privileged 的 Pod old,再给命名空间加 enforce=baseline:--dry-run=server 会输出 Warning: existing pods in namespace \"ps-late\" violate the new PodSecurity enforce level \"baseline:latest\" 并列出违规的 Pod(old: privileged);真正加上标签也只给 Warning,old 仍是 Running;之后再创建 privileged 的 new 才被拒。已经在运行的 Pod 不受影响,只对之后创建/更新 Pod 的请求检查。", f=fl(F4, cur=[1, 2], done=[0, 3]), t=tl(S(4), mark=lidx(S(4), '--dry-run=server', '真正加上标签'), done=lidx(S(4), '已经在运行', '再创建一个')), kv=KV([['先 dry-run', '看有多少存量 Pod 违规'], ['不驱逐', '存量 Pod 继续运行,下次重建才会被拒'], ['逐步推进', '先 warn / audit,再 enforce']], ['先 dry-run'])),
]
A = mkartk('k83', 83, 'Kubernetes,Pod Security,PodSecurity admission,baseline,restricted,真实验证,动画演示',
    '在 kind 集群里用命名空间标签实测 Pod Security 准入:baseline 拒绝 privileged、hostNetwork、hostPath 和 NET_ADMIN 但允许 NET_BIND_SERVICE;restricted 对一个普通 Pod 一次列出 4 条违规,补齐才通过且只检查字段不看镜像;warn 模式只返回 Warning;enforce 下 Deployment 创建成功但 ReplicaSet 创建 Pod 时被拒;给已有 Pod 的命名空间加标签只警告、不驱逐,可以先 dry-run。',
    'Pod Security 准入怎么用?baseline 和 restricted 各拒绝什么?warn / audit / enforce 有什么区别?为什么 Deployment 创建成功但 Pod 起不来?给已有命名空间加标签会误杀吗?这篇在 5 个命名空间里把这些情形逐个跑出来。',
    [('4 条一起拒', 'restricted 对一个普通 Pod 同时指出的违规项数'), ('Deployment 不被拦', '检查在创建 Pod 时,不是创建 Deployment 时;看 ReplicaSet 的 FailedCreate 事件'), ('旧 Pod 不动', '加 enforce 标签只对之后的创建/更新生效,存量 Pod 继续运行')],
    [('baseline:挡住已知的提权', '<p>命名空间 <code>ps-base</code> 带 <code>pod-security.kubernetes.io/enforce=baseline</code>:什么都不设的普通 Pod 通过;<code>privileged: true</code> 被拒(<code>violates PodSecurity "baseline:latest": privileged (container "c" must not set securityContext.privileged=true)</code>);<code>hostNetwork</code> 被拒(<code>host namespaces (hostNetwork=true)</code>);<code>hostPath</code> 卷被拒;<code>add: [NET_ADMIN]</code> 被拒(<code>non-default capabilities</code>);<code>add: [NET_BIND_SERVICE]</code> 却能通过——baseline 允许少数默认之外的能力。</p>'),
     ('restricted:一次列出全部违规', '<p><code>enforce=restricted</code> 下同一个普通 Pod 一次被指出 4 条:<code>allowPrivilegeEscalation != false</code>、<code>unrestricted capabilities</code>(要 drop ALL)、<code>runAsNonRoot != true</code>、<code>seccompProfile</code>(要 <code>RuntimeDefault</code> 或 <code>Localhost</code>)。补齐这 4 项后创建成功。去掉 <code>runAsUser</code> 但保留 <code>runAsNonRoot: true</code>(镜像其实是 root)也通过:准入只看字段,不看镜像,真正的拒绝要等 kubelet(<code>CreateContainerConfigError</code>,见上一篇)。</p>'),
     ('warn 与控制器', '<p><code>warn=restricted</code> + <code>enforce=baseline</code> 的命名空间创建普通 Pod:退出码 0、<code>pod/w1 created</code>,同时返回 <code>Warning: would violate PodSecurity "restricted:latest": …</code>。在 <code>enforce=restricted</code> 的命名空间创建不合规的 Deployment:Deployment 本身创建成功(只带 Warning),但 <code>readyReplicas=0</code>,ReplicaSet 的 <code>ReplicaFailure=FailedCreate</code>,事件是 <code>pods "dep-…" is forbidden: violates PodSecurity "restricted:latest"</code>——拒绝发生在 ReplicaSet 创建 Pod 的那一刻,要去 ReplicaSet 的事件里找。</p>'),
     ('给已有命名空间加标签', '<p>先在 <code>ps-late</code> 里创建 privileged 的 Pod <code>old</code>,再加 <code>enforce=baseline</code>:<code>--dry-run=server</code> 会输出 <code>Warning: existing pods in namespace "ps-late" violate the new PodSecurity enforce level "baseline:latest"</code> 并列出 <code>old: privileged</code>;真正加上标签也只给 Warning,<code>old</code> 仍是 Running;之后再创建 privileged 的 <code>new</code> 才被拒。所以推广 Pod Security 的稳妥顺序是:先 dry-run 看存量违规,再 warn / audit,最后 enforce。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,PodSecurity 准入默认开启);用 kubectl apply 创建 Pod / Deployment 并读返回信息(包括 Warning 头);级别版本都是 latest;每种情形各一次',
     '没有验证:audit 模式写入的审计注解(需要审计日志,见 k18);enforce-version 固定到旧版本的差别;AdmissionConfiguration 里的 exemptions(按用户名、命名空间、RuntimeClass 豁免);privileged 级别;Pod Security Standards 对 Windows Pod 的规则;ValidatingAdmissionPolicy 实现同类约束(下面一篇)'],
    'Pod Security', PANELS)
